CREATE TABLE local_stores (id VARCHAR(36) PRIMARY KEY, name VARCHAR(120) NOT NULL, address VARCHAR(250) NOT NULL, postcode VARCHAR(6) NOT NULL, latitude DECIMAL(9,6) NOT NULL, longitude DECIMAL(9,6) NOT NULL, pickup_enabled BOOLEAN NOT NULL, delivery_enabled BOOLEAN NOT NULL, delivery_minor BIGINT, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE local_store_listings (id VARCHAR(36) PRIMARY KEY, store_id VARCHAR(36) NOT NULL, variant_id VARCHAR(60) NOT NULL, price_minor BIGINT NOT NULL CHECK(price_minor>=0), mrp_minor BIGINT, stock_quantity INT NOT NULL CHECK(stock_quantity>=0), observed_at TIMESTAMP NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(store_id,variant_id), FOREIGN KEY(store_id) REFERENCES local_stores(id), FOREIGN KEY(variant_id) REFERENCES product_variants(id));
CREATE INDEX idx_local_store_postcode ON local_stores(postcode,active);
CREATE INDEX idx_local_listing_variant ON local_store_listings(variant_id,store_id);
